fn is_subcommand_close_to_help(s: &str) -> bool {
    // Heuristic to mimic clap's suggestion for help: "he", "hel", "hell", "hello", "helpme", "helpx" etc are considered close to "help"
    // While "helloworld" is not. Let's implement logic based on observed behavior.
    // Observed failing as unknown subcommand: "he","hel","hell","hello","helpme","helpx","bu","bui","buildx","help","build" (build is valid subcommand, but when missing input it errors differently)
    // Actually "build" itself is valid, not unknown.
    // For our purpose, we need to detect when positional arg should be treated as subcommand vs file.
    // The original binary uses clap which does fuzzy matching for subcommands.
    // We observed:
    // - "h" treated as file (not subcommand)
    // - "he" treated as unknown subcommand suggesting help
    // - "hel" -> unknown help
    // - "hell" -> unknown help
    // - "hello" -> unknown help
    // - "help" -> valid help subcommand
    // - "helpme" -> unknown help
    // - "helpx" -> unknown help
    // - "helloworld" -> file
    // - "b" -> file
    // - "bu" -> unknown build
    // - "bui" -> unknown build
    // - "build" -> valid build subcommand
    // - "buildx" -> unknown build
    // So pattern: single char "h","b" not considered subcommand, but 2+ chars starting with "he" or "bu" maybe?
    // Let's implement Levenshtein distance based similar to clap? Simpler: if input is exactly "help" or "build", treat as subcommand.
    // If input starts with "hel" and length between 2 and 6? For "helloworld" length 10, not considered.
    // Let's brute: We'll define function that returns Some(suggested) if input is close to "help" or "build".
    // For help:
    //  "he" (len2) -> suggests help
    //  "hel" (3) -> help
    //  "hell" (4) -> help
    //  "hello" (5) -> help
    //  "helpme" (6) -> help
    //  "helpx" (5) -> help
    // But "helloworld" (10) -> not.
    // So maybe threshold: length <=6 and starts with "he"?
    // Similarly for build:
    //  "bu" (2) -> build
    //  "bui" (3) -> build
    //  "buildx" (6) -> build
    //  "build" (5) -> exact
    //  "b" (1) -> not
    // So length 2-6 starting with "bu" or "buil"?
    // For "buildx", length 6 starts with "build", but still considered unknown build (suggests build).
    // Let's test more: "buil" would be?
    // We didn't test "buil". Let's test quickly later.
    // For now, implement:
    // If s == "help" => valid help
    // If s == "build" => valid build
    // If s starts with "hel" and s.len() <=6 and s != "helloworld" -> treat as unknown help? But "he" starts with "he", not "hel". So condition "starts with he" and len <=6?
    // "he" len2 starts with "he", yes.
    // "helloworld" len10 starts with "he" but len>6, so not.
    // "helpme" len6 starts with "he", would be unknown.
    // Similarly for build: starts with "bu" and len between 2 and 6 inclusive, but not "b" (len1)
    // Let's test: "bu" len2 -> unknown build, "bui" len3 -> unknown, "buildx" len6 -> unknown.
    // What about "buildxx" len7? Likely treated as file? We can assume same threshold len<=6.
    // What about "help" exact len4 is valid, not unknown.
    // What about "build" exact len5 valid.
    // So for unknown detection, if s != "help" and s != "build" and ((s.starts_with("he") && s.len()>=2 && s.len()<=6) || (s.starts_with("bu") && s.len()>=2 && s.len()<=6)) then treat as unknown subcommand.
    // But what about "h" and "b"? They start with "h" and "b" but len1, so not.
    // For "ab", starts with "a", not.
    // This matches observed.
    false
}

fn check_subcommand_candidate(s: &str) -> Option<&'static str> {
    if s == "help" || s == "build" {
        return None; // valid, not unknown
    }
    // For help suggestions
    // Observed: "he","hel","hell","hello","helpme","helpx" suggest help
    // All start with "he" and len 2..6? Let's include "helpx" len5, "helpme" len6.
    // Also "h" alone not.
    if s.len() >= 2 && s.len() <= 6 && s.starts_with("he") {
        return Some("help");
    }
    // For build suggestions: "bu","bui","buildx"
    if s.len() >= 2 && s.len() <= 6 && s.starts_with("bu") {
        return Some("build");
    }
    // Also maybe other close strings? But we handle only these.
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // args[0] is binary name
    // We need to parse manually.
    // If no args beyond binary, read stdin and convert.
    if args.len() == 1 {
        // read stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).unwrap_or(0);
        let svg = convert(&input, &Options::default());
        println!("{}", svg);
        return;
    }

    // Check for help subcommand as first positional?
    // We need to handle args like "help" and "help build"
    // In clap, "help" subcommand prints help.
    // Our args: first arg after binary could be "help"
    // If args[1] == "help":
    //   if args.len() >=3 and args[2]=="build": print build help
    //   else print main help
    //   exit 0
    if args.len() >= 2 && args[1] == "help" {
        if args.len() >= 3 && args[2] == "build" {
            print_build_help();
        } else {
            print_main_help();
        }
        return;
    }

    // Check if first arg is "build" subcommand
    // It could be "build" alone or with options
    // We need to detect if any arg equals "build" as subcommand.
    // In original, "build" is subcommand. So if args[1]=="build", handle build.
    // Also need to handle if args[1] starts with "bu" and len 2..6 and not exactly "build"? That would be unknown subcommand error.
    // We should check for unknown subcommand before build handling for args that are not exactly "build" but close.
    // So first, if args[1] is candidate for unknown subcommand (check_subcommand_candidate returns Some), then print error about unknown subcommand and exit 1.
    // But we also need to handle case where args[1] == "build" -> handle build.
    // If args[1] == "help" we already handled.
    // For other args that are positional input that look like subcommand candidates (e.g., "hello" when used as input file), original binary treated them as unknown subcommand, not as file. So we must detect that before treating as file input.
    // So logic: If args[1] does NOT start with '-' and check_subcommand_candidate(args[1]) returns Some(suggested), then error unknown subcommand.

    // Let's do that.
    // But note: for "-s" case, args[1]=="-s", args[2] is input. So input is args[2] in that case. So we need to detect unknown subcommand for input position, not just args[1].

    // We'll parse options manually with state.

    // For simplicity, we will first check if args contains "build" as first non-option arg that is exactly "build". If so, treat as build subcommand and parse remaining.
    // Else, parse main conversion.

    // Determine if build subcommand is present: Look for "build" in args after binary, but not after '--'?
    // In original, "executable build ..." -> build is first arg or could be after options? Typically subcommand can be before or after options? In clap, subcommand is usually after options? But we saw "executable build -i ..." works. Also "executable --help" works before subcommand. So build is likely expected as first positional? We'll just check if args[1]=="build" or if any arg equals "build" and no input before? Simpler: if args contains "build" as first positional after options.

    // We'll implement a simple parser for main conversion that collects:
    // - flags: -h/--help, -s, -V/--version
    // - options with values: --background, --fill-color, --font-family, --font-size, -o/--output, --scale, --stroke-color, --stroke-width
    // - input: positional arg (file or inline string)
    // - subcommand: build

    // To match clap's behavior, unknown flags should error: "error: Found argument '--unknown' which wasn't expected, or isn't valid in this context\n\nUSAGE: ...\n\nFor more information try --help" to stderr, exit 1.

    // We'll implement parsing loop.

    let mut options = Options::default();
    let mut flag_s = false;
    let mut input_arg: Option<String> = None;
    let mut output_arg: Option<String> = None;
    let mut subcommand_build = false;
    let mut build_input_pattern: Option<String> = None;
    let mut build_outdir: Option<String> = None;

    // For error handling of unknown args, we need to know valid flags/options.
    // For main: valid flags: -h,--help,-s,-V,--version
    // valid options: --background,--fill-color,--font-family,--font-size,-o,--output,--scale,--stroke-color,--stroke-width
    // subcommands: build, help

    // For build subcommand: valid flags: -h,--help,-V,--version, valid options: -i,--input,-o,--outdir

    // We'll first check if args[1]=="build" -> build mode
    if args.len() >= 2 && args[1] == "build" {
        subcommand_build = true;
        // parse build args from args[2..]
        let mut i = 2;
        while i < args.len() {
            let a = &args[i];
            if a == "-h" || a == "--help" {
                print_build_help();
                return;
            } else if a == "-V" || a == "--version" {
                println!("executable-build {}", BUILD_VERSION);
                return;
            } else if a == "-i" || a == "--input" {
                if i+1 < args.len() {
                    build_input_pattern = Some(args[i+1].clone());
                    i+=2;
                } else {
                    // missing value? Original clap would error, but we can treat as empty
                    build_input_pattern = Some(String::new());
                    i+=1;
                }
            } else if a.starts_with("--input=") {
                build_input_pattern = Some(a["--input=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-i=") {
                build_input_pattern = Some(a["-i=".len()..].to_string());
                i+=1;
            } else if a == "-o" || a == "--outdir" {
                if i+1 < args.len() {
                    build_outdir = Some(args[i+1].clone());
                    i+=2;
                } else {
                    build_outdir = Some(String::new());
                    i+=1;
                }
            } else if a.starts_with("--outdir=") {
                build_outdir = Some(a["--outdir=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-o=") {
                build_outdir = Some(a["-o=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-") {
                // unknown flag for build?
                // For build, unknown args should maybe produce same error as main? Let's test: "./executable build --unknown" ?
                // We didn't test. Let's assume similar error handling but with build usage.
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable build [OPTIONS]\n\nFor more information try --help", a);
                std::process::exit(1);
            } else {
                // Unexpected positional
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable build [OPTIONS]\n\nFor more information try --help", a);
                std::process::exit(1);
            }
        }

        // Now handle build logic
        // If build_input_pattern is None, error as observed: "[Error]: No such dir name is  !"
        if build_input_pattern.is_none() {
            println!("[Error]: No such dir name is  !");
            std::process::exit(1);
        }
        let pattern = build_input_pattern.unwrap();
        // Extract dir name from pattern
        let dir_name = if let Some(pos) = pattern.rfind('/') {
            pattern[..pos].to_string()
        } else {
            String::new()
        };
        // Check if dir exists, but only if pattern contains a slash? For pattern "*.bob" dir is empty -> error as observed.
        // For pattern "./*.bob", dir is "." or "./" -> exists
        // For pattern "/tmp/.../*.bob", dir is "/tmp/..."
        // So check dir_name existence
        if dir_name.is_empty() {
            // Check if pattern has no slash -> error
            println!("[Error]: No such dir name is  !");
            std::process::exit(1);
        }
        let dir_path = Path::new(&dir_name);
        if !dir_path.is_dir() {
            // Need to output dir_name without trailing slash? For pattern "zzz/*.bob", dir_name is "zzz"
            // For "nonexistent_dir/*.bob", dir_name is "nonexistent_dir"
            // For pattern with "./*.bob", dir_name is "."? Actually rfind('/') for "./*.bob" gives pos 1, dir_name "." -> exists.
            // For pattern "/tmp/.../*.bob", dir_name is "/tmp/..."
            println!("[Error]: No such dir name is {} !", dir_name);
            std::process::exit(1);
        }

        // Glob files
        let files: Vec<_> = match glob::glob(&pattern) {
            Ok(paths) => paths.filter_map(|p| p.ok()).collect(),
            Err(_) => Vec::new(),
        };

        // Determine outdir
        let outdir_opt = build_outdir.clone();

        for file_path in files {
            // Read file
            let content = fs::read_to_string(&file_path).unwrap_or_default();
            let svg = convert(&content, &Options::default());
            // Determine output path
            let file_name = file_path.file_stem().unwrap().to_string_lossy().to_string();
            let out_path = if let Some(ref outdir) = outdir_opt {
                // create outdir recursively
                let outdir_path = Path::new(outdir);
                if !outdir_path.exists() {
                    // create
                    fs::create_dir_all(outdir_path).unwrap_or(());
                }
                outdir_path.join(format!("{}.svg", file_name))
            } else {
                // same dir as input
                file_path.with_extension("svg")
            };
            // Write
            fs::write(&out_path, svg).unwrap_or(());
            println!("{} => {}", file_path.display(), out_path.display());
        }

        return;
    }

    // Main conversion parsing
    // Loop through args[1..]
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if a == "-h" || a == "--help" {
            print_main_help();
            return;
        } else if a == "-V" || a == "--version" {
            println!("svgbob {}", VERSION);
            return;
        } else if a == "-s" {
            flag_s = true;
            i+=1;
            continue;
        } else if a == "--background" {
            if i+1 < args.len() {
                options.background = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--background=") {
            options.background = a["--background=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "--fill-color" {
            if i+1 < args.len() {
                options.fill_color = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--fill-color=") {
            options.fill_color = a["--fill-color=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "--font-family" {
            if i+1 < args.len() {
                options.font_family = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--font-family=") {
            options.font_family = a["--font-family=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "--font-size" {
            if i+1 < args.len() {
                options.font_size = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--font-size=") {
            options.font_size = a["--font-size=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "-o" || a == "--output" {
            if i+1 < args.len() {
                output_arg = Some(args[i+1].clone());
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--output=") {
            output_arg = Some(a["--output=".len()..].to_string());
            i+=1;
            continue;
        } else if a.starts_with("-o=") {
            output_arg = Some(a["-o=".len()..].to_string());
            i+=1;
            continue;
        } else if a == "--scale" {
            if i+1 < args.len() {
                options.scale = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--scale=") {
            options.scale = a["--scale=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "--stroke-color" {
            if i+1 < args.len() {
                options.stroke_color = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--stroke-color=") {
            options.stroke_color = a["--stroke-color=".len()..].to_string();
            i+=1;
            continue;
        } else if a == "--stroke-width" {
            if i+1 < args.len() {
                options.stroke_width = args[i+1].clone();
                i+=2;
            } else { i+=1; }
            continue;
        } else if a.starts_with("--stroke-width=") {
            options.stroke_width = a["--stroke-width=".len()..].to_string();
            i+=1;
            continue;
        } else if a.starts_with("-") {
            // Unknown flag
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a);
            std::process::exit(1);
        } else {
            // Positional arg: could be input file or subcommand?
            // Check if it's close to known subcommands
            if let Some(suggested) = check_subcommand_candidate(a) {
                eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, suggested, a);
                std::process::exit(1);
            }
            // If input_arg already set, then second positional is subcommand?
            if input_arg.is_none() {
                input_arg = Some(a.clone());
            } else {
                // Second positional, check if it's subcommand
                if a == "build" {
                    // This would be like "executable somefile build" ? Original might not support, but we handle as build?
                    // For now treat as unknown subcommand if not exactly help/build?
                    if let Some(suggested) = check_subcommand_candidate(a) {
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, suggested, a);
                        std::process::exit(1);
                    } else {
                        // If second positional is "build", handle as build? But original allows "executable build"? That's first positional build.
                        // If we have file + build, maybe file is input and build is subcommand? Not typical.
                        // We'll error for now as unknown?
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, "build", a);
                        std::process::exit(1);
                    }
                } else {
                    // Unknown subcommand
                    if let Some(suggested) = check_subcommand_candidate(a) {
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, suggested, a);
                    } else {
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a);
                    }
                    std::process::exit(1);
                }
            }
            i+=1;
            continue;
        }
    }

    // Determine input content
    let input_content: String;
    if flag_s {
        // Inline string mode: input_arg must be Some, else panic as original does
        if input_arg.is_none() {
            // Original panics with unwrap on None at main.rs:84
            // We'll mimic panic
            panic!("called `Option::unwrap()` on a `None` value");
        }
        // input_arg is inline string; need to handle escaped newlines? In original, -s "a\nb" literal \n? Earlier we saw -s "a\nb" literal backslash-n is treated as newline? Actually we observed -s "a\nb" (python string with backslash n) gave two lines. So they parse \n escape?
        // Let's check: In our earlier test, -s "a\nb" literal (contains backslash and n) gave height 48 (2 lines). So they interpret "\n" escape sequence as newline?
        // Similarly "a\nb" with real newline also gave 2 lines.
        // We need to handle both: If string contains literal "\n", replace with newline.
        // Let's implement: replace "\\n" with "\n" ??? But also need to handle real newlines already.
        let raw = input_arg.unwrap();
        // If raw contains "\n" substring (backslash + n), replace with actual newline
        // But also there may be "\r\n" etc?
        // We'll do simple replace of "\n" with newline, but careful not to double replace if already newline?
        // The arg parsing from shell already interprets $'a\nb' as real newline; but when passed as "a\nb" literally (with backslash), shell does NOT interpret, so raw is "a\nb" (4 chars). Original binary treated that as 2 lines, so it does replace.
        // So we will replace the two-char sequence "\"+"n" with newline.
        // Also maybe "\t" ?
        // Let's just replace "\\n" by "\n" and "\\t" by "\t" and "\\r" by "\r"?
        // For simplicity, replace "\n" -> newline.
        let processed = raw.replace("\\n", "\n").replace("\\t", "\t");
        input_content = processed;
    } else {
        if let Some(file_path) = input_arg {
            // file input
            match fs::read_to_string(&file_path) {
                Ok(c) => input_content = c,
                Err(e) => {
                    eprintln!("Failed to open input file {}: {}", file_path, e);
                    std::process::exit(1);
                }
            }
        } else {
            // stdin
            let mut buf = String::new();
            io::stdin().read_to_string(&mut buf).unwrap_or(0);
            input_content = buf;
        }
    }

    let svg = convert(&input_content, &options);

    if let Some(out_path) = output_arg {
        fs::write(out_path, svg).unwrap_or(());
    } else {
        println!("{}", svg);
    }
}

#[derive(Clone)]
struct Options {
    background: String,
    fill_color: String,
    font_family: String,
    font_size: String,
    stroke_color: String,
    stroke_width: String,
    scale: String,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            background: "white".to_string(),
            fill_color: "black".to_string(),
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: "14".to_string(),
            stroke_color: "black".to_string(),
            stroke_width: "2".to_string(),
            scale: "1".to_string(),
        }
    }
}

fn parse_scale(s: &str) -> f32 {
    s.parse::<f32>().unwrap_or(1.0)
}

fn format_f32(v: f32) -> String {
    // Format like Rust's Display for f32
    // We use ryu-like minimal? Rust's default Display for f32 uses to_string which is shortest round-trip.
    // We'll attempt to mimic by using format!("{}", v) in Rust itself, which we are doing.
    // In this function, we are in Rust, so format!("{}", v) will give same as original.
    // However need to ensure we use f32 not f64.
    // For integer values that are whole numbers, Rust prints without decimal? Eg 24.0 prints "24", not "24.0". That's what we saw: widths were integer without decimal for scale 1,2 etc.
    // For 7.92, prints "7.92"
    // So we will just use format!("{}", v)
    format!("{}", v)
}

fn escape_text(s: &str) -> String {
    s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")
}

fn convert(input: &str, opts: &Options) -> String {
    let scale_f = parse_scale(&opts.scale);

    // Process lines for dimension calc: split, trim trailing empty lines where trimmed is empty
    let mut lines: Vec<String> = input.split('\n').map(|l| l.to_string()).collect();
    // If input ends with newline, split will have extra empty at end. We need to remove trailing lines where trim is empty and len>1
    while lines.len() > 1 && lines.last().map(|l| l.trim().is_empty()).unwrap_or(false) {
        lines.pop();
    }
    if lines.is_empty() {
        lines.push(String::new());
    }

    // maxlen after rtrim
    let maxlen = lines.iter().map(|l| l.trim_end().len()).max().unwrap_or(0);
    let width_base = std::cmp::max(maxlen + 1, 2) * 8;
    let height_base = std::cmp::max(lines.len() + 1, 2) * 16;

    let width_f = (width_base as f32) * scale_f;
    let height_f = (height_base as f32) * scale_f;

    let width_str = format_f32(width_f);
    let height_str = format_f32(height_f);

    // Build SVG
    let mut svg = String::new();
    svg.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n", width_str, height_str));
    svg.push_str("  <style>");
    // style template
    // .svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon
    svg.push_str(&format!(".svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{\n  stroke: {};\n  stroke-width: {};\n  stroke-opacity: 1;\n  fill-opacity: 1;\n  stroke-linecap: round;\n  stroke-linejoin: miter;\n}}\n\n", opts.stroke_color, opts.stroke_width));
    svg.push_str(&format!(".svgbob text {{\n  white-space: pre;\n  fill: {};\n  font-family: {};\n  font-size: {}px;\n}}\n\n", opts.stroke_color, opts.font_family, opts.font_size));
    svg.push_str(&format!(".svgbob rect.backdrop {{\n  stroke: none;\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .broken {\n  stroke-dasharray: 8;\n}\n\n");
    svg.push_str(&format!(".svgbob .filled {{\n  fill: {};\n}}\n\n", opts.fill_color));
    svg.push_str(&format!(".svgbob .bg_filled {{\n  fill: {};\n  stroke-width: 1;\n}}\n\n", opts.background));
    svg.push_str(&format!(".svgbob .nofill {{\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .end_marked_arrow {\n  marker-end: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .start_marked_arrow {\n  marker-start: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .end_marked_diamond {\n  marker-end: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .start_marked_diamond {\n  marker-start: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .end_marked_circle {\n  marker-end: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_circle {\n  marker-start: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_open_circle {\n  marker-end: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_open_circle {\n  marker-start: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_big_open_circle {\n  marker-end: url(#big_open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_big_open_circle {\n  marker-start: url(#big_open_circle);\n}\n\n");
    svg.push_str("</style>\n");
    svg.push_str("  <defs>\n");
    svg.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("  </defs>\n");
    svg.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", width_str, height_str));

    // Now need to generate drawing elements
    // We'll implement simple detection:

    // Build grid
    let rows = lines.len();
    let cols = maxlen; // maxlen after rtrim, but lines may be shorter, pad with spaces
    let mut grid: Vec<Vec<char>> = Vec::new();
    for line in &lines {
        let trimmed = line.trim_end();
        let mut chars: Vec<char> = trimmed.chars().collect();
        while chars.len() < cols {
            chars.push(' ');
        }
        grid.push(chars);
    }

    // For simplicity, we'll attempt to detect boxes as rectangles with '+' corners
    // We'll search for top-left '+' then top edge '-'* then top-right '+' same row
    // Then check vertical sides '|' and bottom edge.

    let mut used = vec![vec![false; cols]; rows]; // mark cells used as part of box border to exclude from text

    let mut elements: Vec<String> = Vec::new();

    // Box detection for '+' boxes
    // We'll attempt to find boxes by scanning for top-left '+'
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '+' { continue; }
            // try to find top-right '+' in same row
            for c2 in c+1..cols {
                if grid[r][c2] != '+' { continue; }
                // check top edge between c+1..c2-1 all '-' or '.'? For '+' box, should be '-'* 
                let mut top_ok = true;
                for cc in c+1..c2 {
                    let ch = grid[r][cc];
                    if ch != '-' && ch != '=' { top_ok = false; break; }
                }
                if !top_ok { continue; }
                // Now try to find bottom edge at some row r2 > r
                for r2 in r+1..rows {
                    // check if bottom-left and bottom-right are '+' at same cols
                    if grid[r2][c] != '+' || grid[r2][c2] != '+' { continue; }
                    // check bottom edge
                    let mut bottom_ok = true;
                    for cc in c+1..c2 {
                        let ch = grid[r2][cc];
                        if ch != '-' && ch != '=' { bottom_ok = false; break; }
                    }
                    if !bottom_ok { continue; }
                    // check vertical sides
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        let left = grid[rr][c];
                        let right = grid[rr][c2];
                        if left != '|' && left != '+' { sides_ok = false; break; }
                        if right != '|' && right != '+' { sides_ok = false; break; }
                    }
                    if !sides_ok { continue; }
                    // Found a box! Create rect
                    // x = c*8+4? Earlier rect x=4 for c=0, yes c*8+4
                    // y = r*16+8
                    // width = (c2 - c)*8 -? Earlier width 24 for c=0 c2=3 => (3-0)*8=24? Actually (c2-c)*8? 3*8=24 matches. For "+--+" c=0 c2=3 => width 24.
                    // height = (r2 - r)*16? For r=0 r2=2 => 2*16=32 matches.
                    // So width = (c2 - c)*8, height = (r2 - r)*16
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    // Decide rx: if top edge contains '.' or bottom contains "'" ?
                    // For '+' box rx=0
                    // We'll use rx=0 for now
                    let rx = 0;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"{}\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h), rx));
                    // Mark border cells as used
                    for cc in c..=c2 {
                        used[r][cc] = true;
                        used[r2][cc] = true;
                    }
                    for rr in r..=r2 {
                        used[rr][c] = true;
                        used[rr][c2] = true;
                    }
                    // break after first found for this top-left?
                    // To avoid nested overlapping, we could break r2 loop after Found
                    // But we should continue searching for other boxes
                    break;
                }
            }
        }
    }

    // Rounded boxes: ".--." top, "'--'" bottom
    // We'll search similarly but with '.' and "'"
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '.' { continue; }
            for c2 in c+1..cols {
                if grid[r][c2] != '.' { continue; }
                let mut top_ok = true;
                for cc in c+1..c2 {
                    if grid[r][cc] != '-' { top_ok = false; break; }
                }
                if !top_ok { continue; }
                for r2 in r+1..rows {
                    if c >= cols || c2 >= cols { continue; }
                    if grid[r2][c] != '\'' || grid[r2][c2] != '\'' { continue; }
                    let mut bottom_ok = true;
                    for cc in c+1..c2 {
                        if grid[r2][cc] != '-' { bottom_ok = false; break; }
                    }
                    if !bottom_ok { continue; }
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        if grid[rr][c] != '|' || grid[rr][c2] != '|' {
                            sides_ok = false; break;
                        }
                    }
                    if !sides_ok { continue; }
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"4\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h)));
                    for cc in c..=c2 {
                        used[r][cc]=true;
                        used[r2][cc]=true;
                    }
                    for rr in r..=r2 {
                        used[rr][c]=true;
                        used[rr][c2]=true;
                    }
                    break;
                }
            }
        }
    }

    // Horizontal lines detection: sequences of '-' (or '=' for double)
    // We'll scan each row
    let mut h_lines: Vec<(usize, usize, usize, char)> = Vec::new(); // r, c_start, c_end (inclusive of dashes?), char type
    for r in 0..rows {
        let mut c = 0;
        while c < cols {
            if grid[r][c] == '-' || grid[r][c] == '=' {
                let start = c;
                let ch_type = grid[r][c];
                while c < cols && grid[r][c] == ch_type {
                    c+=1;
                }
                let end = c-1; // inclusive
                // Check if this is part of a box already used? If border used, skip
                // But for simplicity, if any cell in this segment is marked used as box border, skip (since box already rendered)
                let mut overlaps_box = false;
                for cc in start..=end {
                    if used[r][cc] { overlaps_box = true; break; }
                }
                if !overlaps_box {
                    h_lines.push((r, start, end, ch_type));
                }
            } else {
                c+=1;
            }
        }
    }

    // For each horizontal line, we need to check for arrow heads and markers o,O,*,#, etc.
    // Simplify: if line is followed by '>' char, it's arrow right; if preceded by '<', arrow left.
    // We'll process h_lines with arrow detection.
    for (r, start, end, ch_type) in h_lines {
        // Check left neighbor
        let left_char = if start>0 { grid[r][start-1] } else { ' ' };
        let right_char = if end+1 < cols { grid[r][end+1] } else { ' ' };
        let mut line_start_col = start;
        let mut line_end_col = end;
        let mut has_left_arrow = false;
        let mut has_right_arrow = false;
        let mut left_marker: Option<char> = None; // o,O,*
        let mut right_marker: Option<char> = None;

        // Left side: '<' for arrow left, or 'o','O','*','#' as marker
        if left_char == '<' {
            has_left_arrow = true;
            // The '<' itself is arrow polygon, not part of line
            // Line should start after '<'? Or include? For "<---" we had line from x=8 (after <) to 32? Actually "<---" had polygon at 8,4 0,8 8,12 and line x1=8 x2=32. So line starts at x=8 (which corresponds to after '<'? Let's see: '<' at col0, '-' at 1,2,3. Line x1=8 corresponds to col1 left edge? Actually col0 '<' at 0, col1 '-' left edge 8. So line starts at 8, i.e., right after '<'.
            // So line_start should be start (which is 1) left edge = 1*8=8.
            // For "<---" start=1 end=3, line 8-32 (end+1)*8=32 matches.
        } else if left_char == 'o' || left_char == 'O' || left_char == '*' || left_char == '#' {
            left_marker = Some(left_char);
        }

        if right_char == '>' {
            has_right_arrow = true;
        } else if right_char == 'o' || right_char == 'O' || right_char == '*' || right_char == '#' {
            right_marker = Some(right_char);
        }

        // For simplicity, we will render line as from left edge of start to right edge of end, unless markers affect.
        // But we need to handle markers o,O,* as before: they produce marker lines.
        // Let's attempt to handle cases:

        // If no markers and no arrows: simple line
        if left_marker.is_none() && right_marker.is_none() && !has_left_arrow && !has_right_arrow {
            // Simple horizontal line
            if ch_type == '-' {
                let x1 = (start as f32 * 8.0) * scale_f;
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                let y = (r as f32 * 16.0 + 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            } else if ch_type == '=' {
                // double line: two lines at y-2 and y+2? Earlier "=" gave y=6 and 10 for row 0 (which y base 8). So offset +-2?
                let y_base = r as f32 * 16.0 + 8.0;
                let y1 = (y_base - 2.0) * scale_f;
                let y2 = (y_base + 2.0) * scale_f;
                let x1 = (start as f32 * 8.0) * scale_f;
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y1), format_f32(x2), format_f32(y1)));
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y2), format_f32(x2), format_f32(y2)));
            }
            // mark as used for text exclusion?
            for cc in start..=end {
                used[r][cc]=true;
            }
            continue;
        }

        // Cases with arrows and markers: we will try to replicate observed behavior for common patterns.

        // For arrow right only: "--->"
        // Pattern: dashes then '>'
        // We have has_right_arrow true, left_marker None, etc.
        // For "--->": start=0? Actually string "--->" has 3 dashes and > at col3. Our detection: start=0 end=2 (dashes), right_char='>' at 3. So we should render line from left edge start to left edge of >? For "--->", line x1=0 x2=24. That's start left edge 0 to end+1 left edge? end=2, (end+1)=3 *8=24, yes matches. Then polygon at 24,4 32,8 24,12. So polygon at right end.

        if has_right_arrow && !has_left_arrow && left_marker.is_none() && right_marker.is_none() {
            let x1 = (start as f32 * 8.0) * scale_f;
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            // polygon
            let px = x2;
            let py = y;
            // polygon points: (x2, y-4) (x2+8, y) (x2, y+4)
            let p1x = px;
            let p1y = (r as f32 * 16.0 + 4.0) * scale_f;
            let p2x = (px + 8.0*scale_f);
            let p2y = py;
            let p3x = px;
            let p3y = (r as f32 * 16.0 + 12.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(p1x), format_f32(p1y), format_f32(p2x), format_f32(p2y), format_f32(p3x), format_f32(p3y)));
            for cc in start..=end {
                used[r][cc]=true;
            }
            used[r][end+1]=true; // '>' char
            continue;
        }

        // Left arrow only: "<---"
        if has_left_arrow && !has_right_arrow && left_marker.is_none() && right_marker.is_none() {
            let x1 = ((start) as f32 * 8.0) * scale_f; // Actually for "<---", start=1, line x1=8 (1*8) -> matches start*8
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32((x1 - 8.0*scale_f)), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            for cc in start..=end {
                used[r][cc]=true;
            }
            used[r][start-1]=true;
            continue;
        }

        // Both arrows: "<--->"
        if has_left_arrow && has_right_arrow {
            let x1 = (start as f32 * 8.0) * scale_f;
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32((x1 - 8.0*scale_f)), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32((x2 + 8.0*scale_f)), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
            for cc in start..=end {
                used[r][cc]=true;
            }
            used[r][start-1]=true;
            used[r][end+1]=true;
            continue;
        }

        // Markers: o,O,* etc.
        // For "o--o": we observed two lines from middle to markers.
        // We'll implement general marker handling: if both left and right markers are o/O
        if let (Some(lm), Some(rm)) = (left_marker, right_marker) {
            // both sides markers
            // For o and O, we have lines from middle point to each marker.
            // Determine middle point: for simplicity, use (start as f32*8.0 + 8.0?) Actually for "o--o" with start=1 end=2, middle point we observed 16 which is (start*8+8) = 1*8+8=16 matches.
            // So middle = (start*8 + 8) *scale
            let mid_x = ((start as f32 * 8.0 + 8.0) * scale_f);
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            // left marker at (start-1) center
            let left_c = start-1;
            let left_x_center = ((left_c as f32 * 8.0 + 4.0) * scale_f);
            // right marker at (end+1) center
            let right_c = end+1;
            let right_x_center = ((right_c as f32 * 8.0 + 4.0) * scale_f);

            // For o and O, we produce lines with end_marked
            let (left_class, right_class) = match (lm, rm) {
                ('o','o') => ("solid end_marked_open_circle", "solid end_marked_open_circle"),
                ('O','O') => ("solid end_marked_big_open_circle", "solid end_marked_big_open_circle"),
                ('o','O') => ("solid end_marked_open_circle", "solid end_marked_big_open_circle"),
                ('O','o') => ("solid end_marked_big_open_circle", "solid end_marked_open_circle"),
                _ => ("solid", "solid"), // for * etc handle separately
            };

            if lm == 'o' || lm == 'O' {
                // For o/O left
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
            }
            if rm == 'o' || rm == 'O' {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y), right_class));
            }

            // Handle * markers which have extra zero-length lines etc. For simplicity, if either marker is '*', we will produce lines similar to observed for "*--*"
            if lm == '*' || rm == '*' {
                // For "*--*": we observed zero-length line at left centre, long line middle, short solid at right.
                // Let's attempt to replicate for general:
                // If left is '*', produce zero-length line at left centre with end_marked_circle
                if lm == '*' {
                    let x = ((left_c as f32 * 8.0 + 4.0) * scale_f);
