cat > src/main.rs <<'RS'
use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};

const VERSION: &str = "0.7.6";
const BUILD_VERSION: &str = "0.0.1";

fn print_main_help() {
    println!("svgbob {}\nSvgBobRus is an ascii to svg converter\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)");
}

fn print_build_help() {
    println!("executable-build {}\nBatch convert files to svg.\n\nUSAGE:\n    executable build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files", BUILD_VERSION);
}

fn check_subcommand_candidate(s: &str) -> Option<&'static str> {
    if s == "help" || s == "build" {
        return None;
    }
    if s.len() >= 2 && s.len() <= 6 && s.starts_with("he") {
        return Some("help");
    }
    if s.len() >= 2 && s.len() <= 6 && s.starts_with("bu") {
        return Some("build");
    }
    None
}

fn simple_glob(pattern: &str) -> Vec<PathBuf> {
    // Very simple glob: only supports * wildcard, and pattern like dir/*.ext or *.ext
    // We'll split dir and file pattern
    let (dir_part, file_pat) = if let Some(pos) = pattern.rfind('/') {
        (&pattern[..pos], &pattern[pos+1..])
    } else {
        (".", pattern)
    };
    // For our use, dir_part should be a directory that exists (checked before)
    // file_pat may contain *
    // We'll read dir and filter
    let mut results = Vec::new();
    let dir_path = Path::new(dir_part);
    if let Ok(entries) = fs::read_dir(dir_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                let file_name = path.file_name().unwrap().to_string_lossy();
                if simple_match(&file_name, file_pat) {
                    results.push(path);
                }
            }
        }
    }
    results
}

fn simple_match(name: &str, pat: &str) -> bool {
    // only support * wildcard, e.g., *.bob or a*.bob or *a.bob etc.
    // We'll implement simple: split pat by '*'
    if !pat.contains('*') {
        return name == pat;
    }
    // For "*.bob": prefix "", suffix ".bob"
    // For "a*.bob": prefix "a", suffix ".bob"
    // We'll handle only one *
    let parts: Vec<&str> = pat.split('*').collect();
    if parts.len() == 2 {
        let prefix = parts[0];
        let suffix = parts[1];
        return name.starts_with(prefix) && name.ends_with(suffix);
    }
    // More than one *? fallback to contains
    // For simplicity, if pattern has multiple *, just check if all parts appear in order
    let mut idx = 0;
    for part in parts {
        if part.is_empty() { continue; }
        if let Some(pos) = name[idx..].find(part) {
            idx += pos + part.len();
        } else {
            return false;
        }
    }
    true
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() == 1 {
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).unwrap_or(0);
        let svg = convert(&input, &Options::default());
        println!("{}", svg);
        return;
    }

    if args.len() >= 2 && args[1] == "help" {
        if args.len() >= 3 && args[2] == "build" {
            print_build_help();
        } else {
            print_main_help();
        }
        return;
    }

    if args.len() >= 2 && args[1] == "build" {
        let mut build_input_pattern: Option<String> = None;
        let mut build_outdir: Option<String> = None;
        let mut i = 2;
        while i < args.len() {
            let a = &args[i];
            if a == "-h" || a == "--help" {
