                } else {
                    build_input_pattern = Some(String::new());
                    i+=1;
                }
            } else if a.starts_with("--input=") {
                build_input_pattern = Some(a["--input=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-i=") {
                build_input_pattern = Some(a["-i=".len()..].to_string());
                i+=1;
            } else if a == "-o" || a == "--outdir" {
