                }
            } else if a.starts_with("--outdir=") {
                build_outdir = Some(a["--outdir=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-o=") {
                build_outdir = Some(a["-o=".len()..].to_string());
                i+=1;
            } else if a.starts_with("-") {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable build [OPTIONS]\n\nFor more information try --help", a);
                std::process::exit(1);
            } else {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable build [OPTIONS]\n\nFor more information try --help", a);
                std::process::exit(1);
            }
        }

        if build_input_pattern.is_none() {
            println!("[Error]: No such dir name is  !");
