fn simple_match(name: &str, pat: &str) -> bool {
    if !pat.contains('*') {
        return name == pat;
    }
    let parts: Vec<&str> = pat.split('*').collect();
    if parts.len() == 2 {
        let prefix = parts[0];
        let suffix = parts[1];
        return name.starts_with(prefix) && name.ends_with(suffix);
    }
    let mut idx = 0;
    for part in parts {
        if part.is_empty() { continue; }
        if let Some(pos) = name[idx..].find(part) {
