    svg.push_str(&format!(".svgbob rect.backdrop {{\n  stroke: none;\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .broken {\n  stroke-dasharray: 8;\n}\n\n");
    svg.push_str(&format!(".svgbob .filled {{\n  fill: {};\n}}\n\n", opts.fill_color));
    svg.push_str(&format!(".svgbob .bg_filled {{\n  fill: {};\n  stroke-width: 1;\n}}\n\n", opts.background));
    svg.push_str(&format!(".svgbob .nofill {{\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .end_marked_arrow {\n  marker-end: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .start_marked_arrow {\n  marker-start: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .end_marked_diamond {\n  marker-end: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .start_marked_diamond {\n  marker-start: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .end_marked_circle {\n  marker-end: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_circle {\n  marker-start: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_open_circle {\n  marker-end: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_open_circle {\n  marker-start: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_big_open_circle {\n  marker-end: url(#big_open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_big_open_circle {\n  marker-start: url(#big_open_circle);\n}\n\n");
    svg.push_str("</style>\n");
    svg.push_str("  <defs>\n");
    svg.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("  </defs>\n");
    svg.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", width_str, height_str));

    let rows = lines.len();
    let cols = maxlen;
    let mut grid: Vec<Vec<char>> = Vec::new();
    for line in &lines {
        let trimmed = line.trim_end();
        let mut chars: Vec<char> = trimmed.chars().collect();
        while chars.len() < cols {
            chars.push(' ');
        }
        grid.push(chars);
    }

    let mut used = vec![vec![false; cols]; rows];
    let mut elements: Vec<String> = Vec::new();

    // Boxes '+'
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '+' { continue; }
            for c2 in c+1..cols {
                if grid[r][c2] != '+' { continue; }
                let mut top_ok = true;
                for cc in c+1..c2 {
                    let ch = grid[r][cc];
                    if ch != '-' && ch != '=' { top_ok = false; break; }
                }
                if !top_ok { continue; }
                for r2 in r+1..rows {
                    if grid[r2][c] != '+' || grid[r2][c2] != '+' { continue; }
                    let mut bottom_ok = true;
                    for cc in c+1..c2 {
                        let ch = grid[r2][cc];
                        if ch != '-' && ch != '=' { bottom_ok = false; break; }
                    }
                    if !bottom_ok { continue; }
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        let left = grid[rr][c];
                        let right = grid[rr][c2];
                        if left != '|' && left != '+' { sides_ok = false; break; }
                        if right != '|' && right != '+' { sides_ok = false; break; }
                    }
                    if !sides_ok { continue; }
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"0\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h)));
                    for cc in c..=c2 {
                        used[r][cc] = true;
                        used[r2][cc] = true;
                    }
                    for rr in r..=r2 {
                        used[rr][c] = true;
                        used[rr][c2] = true;
                    }
                    break;
                }
            }
        }
    }

    // Rounded boxes
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '.' { continue; }
            for c2 in c+1..cols {
                if grid[r][c2] != '.' { continue; }
                let mut top_ok = true;
                for cc in c+1..c2 {
                    if grid[r][cc] != '-' { top_ok = false; break; }
                }
                if !top_ok { continue; }
                for r2 in r+1..rows {
                    if c >= cols || c2 >= cols { continue; }
                    if grid[r2][c] != '\'' || grid[r2][c2] != '\'' { continue; }
                    let mut bottom_ok = true;
                    for cc in c+1..c2 {
                        if grid[r2][cc] != '-' { bottom_ok = false; break; }
                    }
                    if !bottom_ok { continue; }
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        if grid[rr][c] != '|' || grid[rr][c2] != '|' { sides_ok=false; break; }
                    }
                    if !sides_ok { continue; }
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"4\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h)));
                    for cc in c..=c2 { used[r][cc]=true; used[r2][cc]=true; }
                    for rr in r..=r2 { used[rr][c]=true; used[rr][c2]=true; }
                    break;
                }
            }
        }
    }

    // Horizontal lines
    let mut h_lines: Vec<(usize, usize, usize, char)> = Vec::new();
    for r in 0..rows {
        let mut c = 0;
        while c < cols {
            if grid[r][c] == '-' || grid[r][c] == '=' {
                let start = c;
                let ch_type = grid[r][c];
                while c < cols && grid[r][c] == ch_type { c+=1; }
                let end = c-1;
                let mut overlaps = false;
                for cc in start..=end {
                    if used[r][cc] { overlaps=true; break; }
                }
                if !overlaps {
                    h_lines.push((r, start, end, ch_type));
                }
            } else { c+=1; }
        }
    }

    for (r, start, end, ch_type) in h_lines {
        let left_char = if start>0 { grid[r][start-1] } else { ' ' };
        let right_char = if end+1 < cols { grid[r][end+1] } else { ' ' };
        let has_left_arrow = left_char == '<';
        let has_right_arrow = right_char == '>';
        let left_marker = match left_char {
            'o'|'O'|'*'|'#' => Some(left_char),
            _ => None
        };
        let right_marker = match right_char {
            'o'|'O'|'*'|'#' => Some(right_char),
            _ => None
        };

        if left_marker.is_none() && right_marker.is_none() && !has_left_arrow && !has_right_arrow {
            if ch_type == '-' {
                let x1 = (start as f32 * 8.0) * scale_f;
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                let y = (r as f32 * 16.0 + 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            } else if ch_type == '=' {
                let y_base = r as f32 * 16.0 + 8.0;
                let y1 = (y_base - 2.0) * scale_f;
                let y2 = (y_base + 2.0) * scale_f;
                let x1 = (start as f32 * 8.0) * scale_f;
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y1), format_f32(x2), format_f32(y1)));
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y2), format_f32(x2), format_f32(y2)));
            }
            for cc in start..=end { used[r][cc]=true; }
            continue;
        }

        if has_right_arrow && !has_left_arrow && left_marker.is_none() && right_marker.is_none() {
            let x1 = (start as f32 * 8.0) * scale_f;
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            let p1x = x2;
            let p1y = (r as f32 * 16.0 + 4.0) * scale_f;
            let p2x = x2 + 8.0*scale_f;
            let p3y = (r as f32 * 16.0 + 12.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(p1x), format_f32(p1y), format_f32(p2x), format_f32(y), format_f32(p1x), format_f32(p3y)));
            for cc in start..=end { used[r][cc]=true; }
            used[r][end+1]=true;
            continue;
        }

        if has_left_arrow && !has_right_arrow && left_marker.is_none() && right_marker.is_none() {
            let x1 = (start as f32 * 8.0) * scale_f;
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            for cc in start..=end { used[r][cc]=true; }
            used[r][start-1]=true;
            continue;
        }

        if has_left_arrow && has_right_arrow {
            let x1 = (start as f32 * 8.0) * scale_f;
            let x2 = ((end+1) as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
            for cc in start..=end { used[r][cc]=true; }
            used[r][start-1]=true;
            used[r][end+1]=true;
            continue;
        }

        // Markers both sides
        if let (Some(lm), Some(rm)) = (left_marker, right_marker) {
            let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            let left_c = start-1;
            let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
            let right_c = end+1;
            let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
            let (left_class, right_class) = match (lm, rm) {
                ('o','o') => ("solid end_marked_open_circle", "solid end_marked_open_circle"),
                ('O','O') => ("solid end_marked_big_open_circle", "solid end_marked_big_open_circle"),
                ('o','O') => ("solid end_marked_open_circle", "solid end_marked_big_open_circle"),
                ('O','o') => ("solid end_marked_big_open_circle", "solid end_marked_open_circle"),
                _ => ("solid", "solid"),
            };
            if lm == 'o' || lm == 'O' {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
            }
            if rm == 'o' || rm == 'O' {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y), right_class));
            }
            if lm == '*' || rm == '*' {
                if lm == '*' {
                    let x = (left_c as f32 * 8.0 + 4.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(x), format_f32(y), format_f32(x), format_f32(y)));
                    let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                    let mid_class = match rm {
                        '*' => "solid end_marked_circle",
                        'o' => "solid end_marked_open_circle",
                        'O' => "solid end_marked_big_open_circle",
                        _ => "solid",
                    };
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center), format_f32(y), mid_class));
                    if rm == '*' {
                        let x1_extra = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1_extra), format_f32(y), format_f32(right_x_center), format_f32(y)));
                    }
                } else if rm == '*' {
                    let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                    let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y)));
                    let x1_extra = (right_c as f32 * 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1_extra), format_f32(y), format_f32(right_x_center), format_f32(y)));
                }
            }
            for cc in start..=end { used[r][cc]=true; }
            used[r][start-1]=true;
            used[r][end+1]=true;
            continue;
        }

        if let Some(lm) = left_marker {
            let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            let left_c = start-1;
            let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
            let left_class = match lm {
                'o' => "solid end_marked_open_circle",
                'O' => "solid end_marked_big_open_circle",
                '*' => "solid end_marked_circle",
                _ => "solid",
            };
            if lm == '*' {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(left_x_center), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                if has_right_arrow {
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                } else {
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                }
            } else {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                if has_right_arrow {
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(mid_x), format_f32(y), format_f32(x2), format_f32(y)));
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                } else {
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(mid_x), format_f32(y), format_f32(x2), format_f32(y)));
                }
            }
            for cc in start..=end { used[r][cc]=true; }
            used[r][start-1]=true;
            if has_right_arrow { used[r][end+1]=true; }
            continue;
        }

        if let Some(rm) = right_marker {
            let x1 = (start as f32 * 8.0) * scale_f;
            let y = (r as f32 * 16.0 + 8.0) * scale_f;
            let right_c = end+1;
            let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
            let class = match rm {
                'o' => "solid end_marked_open_circle",
                'O' => "solid end_marked_big_open_circle",
                '*' => "solid end_marked_circle",
                _ => "solid",
            };
            if rm == '*' {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center - 4.0*scale_f), format_f32(y), class));
                let x1_extra = (end as f32 * 8.0 + 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1_extra), format_f32(y), format_f32(right_x_center), format_f32(y)));
            } else {
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center), format_f32(y), class));
            }
            for cc in start..=end { used[r][cc]=true; }
            used[r][end+1]=true;
            continue;
        }

        let x1 = (start as f32 * 8.0) * scale_f;
        let x2 = ((end+1) as f32 * 8.0) * scale_f;
        let y = (r as f32 * 16.0 + 8.0) * scale_f;
        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
        for cc in start..=end { used[r][cc]=true; }
    }

    // Vertical lines
    let mut v_lines: Vec<(usize, usize, usize)> = Vec::new();
    for c in 0..cols {
        let mut r = 0;
        while r < rows {
            if grid[r][c] == '|' {
                let start = r;
                while r < rows && grid[r][c] == '|' { r+=1; }
                let end = r-1;
                let mut overlaps = false;
                for rr in start..=end {
                    if used[rr][c] { overlaps=true; break; }
                }
                if !overlaps { v_lines.push((c, start, end)); }
            } else { r+=1; }
        }
    }

    for (c, r_start, r_end) in v_lines {
        let x = (c as f32 * 8.0 + 4.0) * scale_f;
        let y1 = (r_start as f32 * 16.0) * scale_f;
        let y2 = ((r_end+1) as f32 * 16.0) * scale_f;
        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x), format_f32(y1), format_f32(x), format_f32(y2)));
        for rr in r_start..=r_end { used[rr][c]=true; }
    }

    // Text
    for r in 0..rows {
        let mut c = 0;
        while c < cols {
            if used[r][c] || grid[r][c] == ' ' {
                c+=1;
                continue;
            }
            let start = c;
            while c < cols && !used[r][c] && grid[r][c] != ' ' {
                let ch = grid[r][c];
                if ch == '-' || ch == '=' || ch == '|' || ch == '+' {
                    break;
                }
                c+=1;
            }
            let end = c;
            if start < end {
                let mut word = String::new();
                for cc in start..end { word.push(grid[r][cc]); }
                let esc = escape_text(&word);
                let x = (start as f32 * 8.0 + 2.0) * scale_f;
                let y = (r as f32 * 16.0 + 12.0) * scale_f;
                elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
            }
            if c < cols && !used[r][c] && grid[r][c] != ' ' {
                let ch = grid[r][c];
                if ch == '+' || ch == '-' || ch == '|' {
                    let esc = escape_text(&ch.to_string());
                    let x = (c as f32 * 8.0 + 2.0) * scale_f;
                    let y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                    c+=1;
                } else {
                    c+=1;
                }
            }
        }
    }

    for el in elements {
        svg.push_str(&el);
        svg.push_str("\n");
    }
    svg.push_str("</svg>\n");
    svg
}
RS
cargo build --release 2>&1 | tail -n 20
./target/release/executable --help 2>&1 | head -n 30
"}

