            options.stroke_width = a["--stroke-width=".len()..].to_string(); i+=1; continue;
        } else if a.starts_with("-") {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a);
            std::process::exit(1);
        } else {
            if let Some(suggested) = check_subcommand_candidate(a) {
                eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, suggested, a);
                std::process::exit(1);
            }
            if input_arg.is_none() {
                input_arg = Some(a.clone());
            } else {
                if a == "build" {
                    eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, "build", a);
                    std::process::exit(1);
                } else {
                    if let Some(suggested) = check_subcommand_candidate(a) {
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with 'executable -- {}'\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a, suggested, a);
                    } else {
                        eprintln!("error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFor more information try --help", a);
                    }
                    std::process::exit(1);
                }
            }
            i+=1;
            continue;
        }
    }

    let input_content: String;
    if flag_s {
        if input_arg.is_none() {
            panic!("called `Option::unwrap()` on a `None` value");
        }
        let raw = input_arg.unwrap();
        let processed = raw.replace("\\n", "\n").replace("\\t", "\t");
        input_content = processed;
    } else {
        if let Some(file_path) = input_arg {
            match fs::read_to_string(&file_path) {
                Ok(c) => input_content = c,
                Err(e) => {
                    eprintln!("Failed to open input file {}: {}", file_path, e);
                    std::process::exit(1);
                }
            }
        } else {
            let mut buf = String::new();
            io::stdin().read_to_string(&mut buf).unwrap_or(0);
            input_content = buf;
        }
    }

    let svg = convert(&input_content, &options);
    if let Some(out_path) = output_arg {
        fs::write(out_path, svg).unwrap_or(());
    } else {
        print!("{}", svg);
    }
}

#[derive(Clone)]
struct Options {
    background: String,
    fill_color: String,
    font_family: String,
    font_size: String,
    stroke_color: String,
    stroke_width: String,
    scale: String,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            background: "white".to_string(),
            fill_color: "black".to_string(),
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: "14".to_string(),
            stroke_color: "black".to_string(),
            stroke_width: "2".to_string(),
            scale: "1".to_string(),
        }
    }
}

fn parse_scale(s: &str) -> f32 {
    s.parse::<f32>().unwrap_or(1.0)
}

fn format_f32(v: f32) -> String {
    format!("{}", v)
}

fn escape_text(s: &str) -> String {
    s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")
}

// Structure to hold horizontal line info
#[derive(Debug, Clone)]
struct HLine {
    r: usize,
    start: usize,
    end: usize,
    ch_type: char,
    left_char: char,
    right_char: char,
}

fn convert(input: &str, opts: &Options) -> String {
    let scale_f = parse_scale(&opts.scale);

    let mut lines: Vec<String> = input.split('\n').map(|l| l.to_string()).collect();
    while lines.len() > 1 && lines.last().map(|l| l.trim().is_empty()).unwrap_or(false) {
        lines.pop();
    }
    if lines.is_empty() {
        lines.push(String::new());
    }

    let maxlen = lines.iter().map(|l| l.trim_end().len()).max().unwrap_or(0);
    let width_base = std::cmp::max(maxlen + 1, 2) * 8;
    let height_base = std::cmp::max(lines.len() + 1, 2) * 16;

    let width_f = (width_base as f32) * scale_f;
    let height_f = (height_base as f32) * scale_f;

    let width_str = format_f32(width_f);
    let height_str = format_f32(height_f);

    let mut svg = String::new();
    svg.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n", width_str, height_str));
    svg.push_str("  <style>");
    svg.push_str(&format!(".svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{\n  stroke: {};\n  stroke-width: {};\n  stroke-opacity: 1;\n  fill-opacity: 1;\n  stroke-linecap: round;\n  stroke-linejoin: miter;\n}}\n\n", opts.stroke_color, opts.stroke_width));
    svg.push_str(&format!(".svgbob text {{\n  white-space: pre;\n  fill: {};\n  font-family: {};\n  font-size: {}px;\n}}\n\n", opts.stroke_color, opts.font_family, opts.font_size));
    svg.push_str(&format!(".svgbob rect.backdrop {{\n  stroke: none;\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .broken {\n  stroke-dasharray: 8;\n}\n\n");
    svg.push_str(&format!(".svgbob .filled {{\n  fill: {};\n}}\n\n", opts.fill_color));
    svg.push_str(&format!(".svgbob .bg_filled {{\n  fill: {};\n  stroke-width: 1;\n}}\n\n", opts.background));
    svg.push_str(&format!(".svgbob .nofill {{\n  fill: {};\n}}\n\n", opts.background));
    svg.push_str(".svgbob .end_marked_arrow {\n  marker-end: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .start_marked_arrow {\n  marker-start: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .end_marked_diamond {\n  marker-end: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .start_marked_diamond {\n  marker-start: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .end_marked_circle {\n  marker-end: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_circle {\n  marker-start: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_open_circle {\n  marker-end: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_open_circle {\n  marker-start: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_big_open_circle {\n  marker-end: url(#big_open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_big_open_circle {\n  marker-start: url(#big_open_circle);\n}\n\n");
    svg.push_str("</style>\n");
    svg.push_str("  <defs>\n");
    svg.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("  </defs>\n");
    svg.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", width_str, height_str));

    let rows = lines.len();
    let cols = maxlen;
    let mut grid: Vec<Vec<char>> = Vec::new();
    for line in &lines {
        let trimmed = line.trim_end();
        let mut chars: Vec<char> = trimmed.chars().collect();
        while chars.len() < cols {
            chars.push(' ');
        }
        grid.push(chars);
    }

    let mut used = vec![vec![false; cols]; rows];
    let mut elements: Vec<String> = Vec::new();

    // Boxes '+'
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '+' || used[r][c] { continue; }
            for c2 in c+1..cols {
                if grid[r][c2] != '+' || used[r][c2] { continue; }
                let mut top_ok = true;
                for cc in c+1..c2 {
                    let ch = grid[r][cc];
                    if ch != '-' && ch != '=' { top_ok=false; break; }
                }
                if !top_ok { continue; }
                for r2 in r+1..rows {
                    if grid[r2][c] != '+' || grid[r2][c2] != '+' { continue; }
                    if used[r2][c] || used[r2][c2] { continue; }
                    let mut bottom_ok = true;
                    for cc in c+1..c2 {
                        let ch = grid[r2][cc];
                        if ch != '-' && ch != '=' { bottom_ok=false; break; }
                    }
                    if !bottom_ok { continue; }
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        let left = grid[rr][c];
                        let right = grid[rr][c2];
                        if left != '|' && left != '+' { sides_ok=false; break; }
                        if right != '|' && right != '+' { sides_ok=false; break; }
                        if used[rr][c] || used[rr][c2] { sides_ok=false; break; }
                    }
                    if !sides_ok { continue; }
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"0\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h)));
                    for cc in c..=c2 { used[r][cc]=true; used[r2][cc]=true; }
                    for rr in r..=r2 { used[rr][c]=true; used[rr][c2]=true; }
                    break;
                }
            }
        }
    }

    // Rounded boxes
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '.' || used[r][c] { continue; }
            for c2 in c+1..cols {
                if grid[r][c2] != '.' || used[r][c2] { continue; }
                let mut top_ok = true;
                for cc in c+1..c2 { if grid[r][cc] != '-' { top_ok=false; break; } }
                if !top_ok { continue; }
                for r2 in r+1..rows {
                    if c>=cols || c2>=cols { continue; }
                    if grid[r2][c] != '\'' || grid[r2][c2] != '\'' { continue; }
                    if used[r2][c] || used[r2][c2] { continue; }
                    let mut bottom_ok = true;
                    for cc in c+1..c2 { if grid[r2][cc] != '-' { bottom_ok=false; break; } }
                    if !bottom_ok { continue; }
                    let mut sides_ok = true;
                    for rr in r+1..r2 {
                        if grid[rr][c] != '|' || grid[rr][c2] != '|' { sides_ok=false; break; }
                        if used[rr][c] || used[rr][c2] { sides_ok=false; break; }
                    }
                    if !sides_ok { continue; }
                    let x = (c as f32 * 8.0 + 4.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    let w = ((c2 - c) as f32 * 8.0) * scale_f;
                    let h = ((r2 - r) as f32 * 16.0) * scale_f;
                    elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"4\"></rect>", format_f32(x), format_f32(y), format_f32(w), format_f32(h)));
                    for cc in c..=c2 { used[r][cc]=true; used[r2][cc]=true; }
                    for rr in r..=r2 { used[rr][c]=true; used[rr][c2]=true; }
                    break;
                }
            }
        }
    }

    // Collect horizontal lines info, but not yet emit
    let mut h_lines_per_row: Vec<Vec<HLine>> = vec![Vec::new(); rows];
    for r in 0..rows {
        let mut c = 0;
        while c < cols {
            if (grid[r][c] == '-' || grid[r][c] == '=') && !used[r][c] {
                let start = c;
                let ch_type = grid[r][c];
                while c < cols && grid[r][c] == ch_type && !used[r][c] {
                    c+=1;
                }
                let end = c-1;
                let left_char = if start>0 { grid[r][start-1] } else { ' ' };
                let right_char = if end+1 < cols { grid[r][end+1] } else { ' ' };
                h_lines_per_row[r].push(HLine{ r, start, end, ch_type, left_char, right_char });
            } else {
                c+=1;
            }
        }
        // sort by start
        h_lines_per_row[r].sort_by_key(|hl| hl.start);
    }

    // Vertical lines per col, group by start
    let mut v_lines: Vec<(usize, usize, usize)> = Vec::new();
    {
        let mut visited_v = vec![vec![false; cols]; rows];
        for c in 0..cols {
            let mut r = 0;
            while r < rows {
                if grid[r][c] == '|' && !used[r][c] && !visited_v[r][c] {
                    let start = r;
                    let mut cur = r;
                    while cur < rows && grid[cur][c] == '|' && !used[cur][c] {
                        visited_v[cur][c]=true;
                        cur+=1;
                    }
                    let end = cur-1;
                    if start <= end {
                        v_lines.push((c, start, end));
                    }
                    r = cur;
                } else {
                    r+=1;
                }
            }
        }
    }
    // Group vertical lines by start row
    let mut v_lines_per_row: Vec<Vec<(usize, usize, usize)>> = vec![Vec::new(); rows];
    for (c, rs, re) in v_lines {
        if rs < rows {
            v_lines_per_row[rs].push((c, rs, re));
        }
    }

    // Now per row emit in order: first vertical lines that start at this row? But also horizontal lines and text interleaved.
    // For each row, we will have a list of pending items sorted by column.
    // For vertical lines, their column is c, but they are vertical, so their x position is at that column.
    // For ordering, we might want vertical lines to be emitted before horizontal lines/text if they are at same row? Let's see for "a--b" case, only horizontal.
    // For "a\n|\nb": row0 has no vertical starting, only text. Row1 has vertical line. Row2 text.
    // So per row: first emit any vertical lines starting at this row, then handle horizontal/text left to right.

    for r in 0..rows {
        // Emit vertical lines starting at r
        for (c, _rs, re) in &v_lines_per_row[r] {
            // Check if still not used
            if used[r][*c] { continue; }
            // Ensure not overlapping used
            let mut overlapped = false;
            for rr in r..=*re {
                if rr < rows && used[rr][*c] {
                    // If first row already used? but we check
                    // Allow first row to be not used, but subsequent rows may be used? We should have ensured not used before
                    if rr != r {
                        // but we already marked visited, so skip?
                    }
                }
            }
            if overlapped { continue; }
            let x = (*c as f32 * 8.0 + 4.0) * scale_f;
            let y1 = (r as f32 * 16.0) * scale_f;
            let y2 = ((*re+1) as f32 * 16.0) * scale_f;
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x), format_f32(y1), format_f32(x), format_f32(y2)));
            for rr in r..=*re {
                if rr < rows {
                    used[rr][*c]=true;
                }
            }
        }

        // Now horizontal and text interleaved
        let mut c = 0;
        // For quick lookup of h_line starting at c, we have list
        // We'll create an index map of h_lines per row by start
        let h_lines = &h_lines_per_row[r];
        let mut h_idx = 0;
        // We need to efficiently find h_line whose start == c or whose left marker is at c-1 etc.
        // Our h_lines store start as first dash column, not including left marker.
        // For ordering, the left marker is at start-1, so the visual start of that element is start-1 if marker present, or start if arrow? For "<---", leftmost is at start-1 (the '<'). So ordering should consider leftmost.
        // To simplify, we will during scanning check if c is start of h_line OR c is left marker of next h_line?
        // Better: At each column c, check if there is h_line with leftmost column == c.
        // Leftmost = if left_char in ['<','o','O','*','#'] then start-1 else start
        // So we need to find h_line whose leftmost == c.

        while c < cols {
            if used[r][c] {
                c+=1;
                continue;
            }

            // Check if any h_line has leftmost == c
            let mut found_h = None;
            let mut found_idx = None;
            for (idx, hl) in h_lines.iter().enumerate() {
                let leftmost = if hl.left_char == '<' || hl.left_char == 'o' || hl.left_char == 'O' || hl.left_char == '*' || hl.left_char == '#' {
                    if hl.start>0 { hl.start-1 } else { hl.start }
                } else {
                    hl.start
                };
                if leftmost == c && !used[r][hl.start] {
                    found_h = Some(hl.clone());
                    found_idx = Some(idx);
                    break;
                }
                if hl.start == c && !used[r][c] {
                    found_h = Some(hl.clone());
                    found_idx = Some(idx);
                    break;
                }
            }

            if let Some(hl) = found_h {
                // Emit this h_line with its markers/arrows
                let start = hl.start;
                let end = hl.end;
                let ch_type = hl.ch_type;
                let left_char = hl.left_char;
                let right_char = hl.right_char;
                let has_left_arrow = left_char == '<';
                let has_right_arrow = right_char == '>';
                let left_marker = match left_char {
                    'o'|'O'|'*'|'#' => Some(left_char),
                    _ => None
                };
                let right_marker = match right_char {
                    'o'|'O'|'*'|'#' => Some(right_char),
                    _ => None
                };

                // Cases
                if left_marker.is_none() && right_marker.is_none() && !has_left_arrow && !has_right_arrow {
                    if ch_type == '-' {
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        let y = (r as f32 * 16.0 + 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    } else {
                        let y_base = r as f32 * 16.0 + 8.0;
                        let y1 = (y_base - 2.0) * scale_f;
                        let y2 = (y_base + 2.0) * scale_f;
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y1), format_f32(x2), format_f32(y1)));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y2), format_f32(x2), format_f32(y2)));
                    }
                    for cc in start..=end { used[r][cc]=true; }
                    c = end+1;
                    continue;
                }

                if has_right_arrow && !has_left_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    let p1x = x2;
                    let p1y = (r as f32 * 16.0 + 4.0) * scale_f;
                    let p2x = x2 + 8.0*scale_f;
                    let p3y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(p1x), format_f32(p1y), format_f32(p2x), format_f32(y), format_f32(p1x), format_f32(p3y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][end+1]=true;
                    c = end+2;
                    continue;
                }

                if has_left_arrow && !has_right_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][start-1]=true;
                    c = end+1;
                    continue;
                }

                if has_left_arrow && has_right_arrow {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
