                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                for cc in start..=end { used[r][cc]=true; }
                c = end+1;
            } else if ch != ' ' && !used[r][c] {
                if ch == '+' || ch == '|' {
                    let esc = escape_text(&ch.to_string());
                    let x = (c as f32 * 8.0 + 2.0) * scale_f;
                    let y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                    used[r][c]=true;
                    c+=1;
                    continue;
                }
                // check if this is a marker that should be text? o, O, * alone are text?
                // We'll treat o,O,* as text if not part of line (handled above)
                let start = c;
                while c < cols && !used[r][c] && grid[r][c] != ' ' {
                    let ch2 = grid[r][c];
                    if ch2 == '-' || ch2 == '=' || ch2 == '|' || ch2 == '+' {
                        break;
                    }
                    // If we encounter a marker char that could be part of line, but we already handled lines starting at this col?
                    // For simplicity, break on '<' '>' as they are arrows or text?
                    if ch2 == '<' || ch2 == '>' {
                        break;
                    }
                    c+=1;
                }
                let end = c;
                if start < end {
                    let mut word = String::new();
                    for cc in start..end { word.push(grid[r][cc]); }
                    let esc = escape_text(&word);
                    let x = (start as f32 * 8.0 + 2.0) * scale_f;
                    let y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                    for cc in start..end { used[r][cc]=true; }
                }
                // If we broke on '<' or '>' that is alone as text, emit as text
                if c < cols && !used[r][c] && grid[r][c] != ' ' {
                    let ch2 = grid[r][c];
                    if ch2 == '<' || ch2 == '>' {
                        // check if it's part of arrow? Already handled as arrow if adjacent to dashes, but if isolated, it's text
                        let esc = escape_text(&ch2.to_string());
                        let x = (c as f32 * 8.0 + 2.0) * scale_f;
                        let y = (r as f32 * 16.0 + 12.0) * scale_f;
                        elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                        used[r][c]=true;
                        c+=1;
                    }
                }
            } else {
                c+=1;
            }
        }
    }

    for el in elements {
        svg.push_str(&el);
        svg.push_str("\n");
    }
    svg.push_str("</svg>\n");
    svg
}
