    let mut h_lines_per_row: Vec<Vec<HLine>> = vec![Vec::new(); rows];
    for r in 0..rows {
        let mut c = 0;
        while c < cols {
            if (grid[r][c] == '-' || grid[r][c] == '=') && !used[r][c] {
                let start = c;
                let ch_type = grid[r][c];
                while c < cols && grid[r][c] == ch_type && !used[r][c] {
                    c+=1;
                }
                let end = c-1;
                let left_char = if start>0 { grid[r][start-1] } else { ' ' };
                let right_char = if end+1 < cols { grid[r][end+1] } else { ' ' };
                h_lines_per_row[r].push(HLine{ r, start, end, ch_type, left_char, right_char });
            } else {
                c+=1;
            }
        }
    }

    // vertical lines
    let mut v_lines: Vec<(usize, usize, usize)> = Vec::new();
    {
        let mut visited_v = vec![vec![false; cols]; rows];
        for c in 0..cols {
            let mut r = 0;
            while r < rows {
                if grid[r][c] == '|' && !used[r][c] && !visited_v[r][c] {
                    let start = r;
                    let mut cur = r;
                    while cur < rows && grid[cur][c] == '|' && !used[cur][c] {
                        visited_v[cur][c]=true;
                        cur+=1;
                    }
                    let end = cur-1;
                    v_lines.push((c, start, end));
                    r = cur;
                } else {
                    r+=1;
                }
            }
        }
    }
    let mut v_lines_per_row: Vec<Vec<(usize, usize, usize)>> = vec![Vec::new(); rows];
    for (c, rs, re) in v_lines {
        if rs < rows {
            v_lines_per_row[rs].push((c, rs, re));
        }
    }

    for r in 0..rows {
        // vertical lines starting at r
        for (c, _rs, re) in &v_lines_per_row[r] {
            if used[r][*c] { continue; }
            let x = (*c as f32 * 8.0 + 4.0) * scale_f;
            let y1 = (r as f32 * 16.0) * scale_f;
            let y2 = ((re+1) as f32 * 16.0) * scale_f;
            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x), format_f32(y1), format_f32(x), format_f32(y2)));
            for rr in r..=*re {
                if rr < rows {
                    used[rr][*c]=true;
                }
            }
        }

        let mut c = 0;
        while c < cols {
            if used[r][c] {
                c+=1;
                continue;
            }

            // check if any h_line has leftmost == c or start == c
            let mut found_h: Option<HLine> = None;
            for hl in &h_lines_per_row[r] {
                let leftmost = if hl.left_char == '<' || hl.left_char == 'o' || hl.left_char == 'O' || hl.left_char == '*' || hl.left_char == '#' || hl.left_char == '+' || hl.left_char == 'X' {
                    if hl.start>0 { hl.start-1 } else { hl.start }
                } else {
                    hl.start
                };
                if leftmost == c && !used[r][hl.start] {
                    found_h = Some(hl.clone());
                    break;
                }
                if hl.start == c && !used[r][c] {
                    found_h = Some(hl.clone());
                    break;
                }
            }

            if let Some(hl) = found_h {
                let start = hl.start;
                let end = hl.end;
                let ch_type = hl.ch_type;
                let left_char = hl.left_char;
                let right_char = hl.right_char;
                let has_left_arrow = left_char == '<';
                let has_right_arrow = right_char == '>';
                let left_marker = match left_char {
                    'o'|'O'|'*'|'#'|'+'|'X' => Some(left_char),
                    _ => None
                };
                let right_marker = match right_char {
                    'o'|'O'|'*'|'#'|'+'|'X' => Some(right_char),
                    _ => None
                };

                // Helper to get centre
                let y = (r as f32 * 16.0 + 8.0) * scale_f;

                if left_marker.is_none() && right_marker.is_none() && !has_left_arrow && !has_right_arrow {
                    if ch_type == '-' {
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    } else {
                        let y_base = r as f32 * 16.0 + 8.0;
                        let y1 = (y_base - 2.0) * scale_f;
                        let y2 = (y_base + 2.0) * scale_f;
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y1), format_f32(x2), format_f32(y1)));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y2), format_f32(x2), format_f32(y2)));
                    }
                    for cc in start..=end { used[r][cc]=true; }
                    c = end+1;
                    continue;
                }

                // arrows
                if has_right_arrow && !has_left_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    let p1y = (r as f32 * 16.0 + 4.0) * scale_f;
                    let p2x = x2 + 8.0*scale_f;
                    let p3y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32(p1y), format_f32(p2x), format_f32(y), format_f32(x2), format_f32(p3y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][end+1]=true;
                    c = end+2;
                    continue;
                }
                if has_left_arrow && !has_right_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][start-1]=true;
                    c = end+1;
                    continue;
                }
                if has_left_arrow && has_right_arrow {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][start-1]=true;
                    used[r][end+1]=true;
                    c = end+2;
                    continue;
                }

                // Both markers
                if let (Some(lm), Some(rm)) = (left_marker, right_marker) {
                    // Handle cases:
                    // o/O with o/O -> two lines from mid
                    // X with X -> single line centre to centre
                    // + with + -> single line centre to centre? Actually +--+
                    // # with # -> rects + line between
                    // * with * -> as before
                    // Mixed cases e.g., X with o, + with o, etc.

                    let left_c = start-1;
                    let right_c = end+1;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;

                    if (lm == '+' || lm == 'X') && (rm == '+' || rm == 'X') {
                        let x1 = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let x2 = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    if lm == '#' && rm == '#' {
                        let x_left = (left_c as f32 * 8.0) * scale_f;
                        let y_rect = (r as f32 * 16.0 + 4.0) * scale_f;
                        let w = (8.0)*scale_f;
                        let h = (8.0)*scale_f;
                        elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_left), format_f32(y_rect), format_f32(w), format_f32(h)));
                        let x_right = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_right), format_f32(y_rect), format_f32(w), format_f32(h)));
                        let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                        let x2 = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    // o/O markers both sides -> two lines from mid
                    if (lm == 'o' || lm == 'O') && (rm == 'o' || rm == 'O') {
                        let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        let (left_class, right_class) = match (lm, rm) {
                            ('o','o') => ("solid end_marked_open_circle", "solid end_marked_open_circle"),
                            ('O','O') => ("solid end_marked_big_open_circle", "solid end_marked_big_open_circle"),
                            ('o','O') => ("solid end_marked_open_circle", "solid end_marked_big_open_circle"),
                            ('O','o') => ("solid end_marked_big_open_circle", "solid end_marked_open_circle"),
                            _ => ("solid", "solid"),
                        };
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y), right_class));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    // * handling both sides
                    if lm == '*' && rm == '*' {
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(left_x_center), format_f32(y), format_f32(left_x_center), format_f32(y)));
                        let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        let x1_extra = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1_extra), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    // Mixed cases: one side +/X and other side o/O
                    if (lm == '+' || lm == 'X') && (rm == 'o' || rm == 'O') {
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_class = match rm {
                            'o' => "solid end_marked_open_circle",
                            'O' => "solid end_marked_big_open_circle",
                            _ => "solid",
                        };
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(left_x_center), format_f32(y), format_f32(right_x_center), format_f32(y), right_class));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }
                    if (rm == '+' || rm == 'X') && (lm == 'o' || lm == 'O') {
                        let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        let left_class = match lm {
                            'o' => "solid end_marked_open_circle",
                            'O' => "solid end_marked_big_open_circle",
                            _ => "solid",
                        };
                        // For o--X pattern, original had two lines: mid->left marker and mid->right solid
                        // Let's emit as per observed: mid->left with marker, mid->right solid
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    // Mixed with #
                    if lm == '#' || rm == '#' {
                        // If left is #, produce rect for #
                        if lm == '#' {
                            let x_left = (left_c as f32 * 8.0) * scale_f;
                            let y_rect = (r as f32 * 16.0 + 4.0) * scale_f;
                            elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_left), format_f32(y_rect), format_f32(8.0*scale_f), format_f32(8.0*scale_f)));
                        }
                        if rm == '#' {
                            let x_right = (right_c as f32 * 8.0) * scale_f;
                            let y_rect = (r as f32 * 16.0 + 4.0) * scale_f;
                            elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_right), format_f32(y_rect), format_f32(8.0*scale_f), format_f32(8.0*scale_f)));
                        }
                        // line between
                        let x1 = if lm == '#' { (left_c as f32 * 8.0 + 8.0) * scale_f } else { (start as f32 * 8.0) * scale_f };
                        let x2 = if rm == '#' { (right_c as f32 * 8.0) * scale_f } else { ((end+1) as f32 * 8.0) * scale_f };
                        // If other side is o/O/*, need marker handling
                        if rm == 'o' || rm == 'O' {
                            let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                            let class = match rm {
                                'o' => "solid end_marked_open_circle",
                                'O' => "solid end_marked_big_open_circle",
                                _ => "solid",
                            };
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center), format_f32(y), class));
                        } else if lm == 'o' || lm == 'O' {
                            let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                            let class = match lm {
                                'o' => "solid end_marked_open_circle",
                                'O' => "solid end_marked_big_open_circle",
                                _ => "solid",
                            };
                            let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), class));
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(mid_x), format_f32(y), format_f32(x2), format_f32(y)));
                        } else {
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                        }
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }

                    // Fallback single line
                    let x1 = (left_c as f32 * 8.0 + 4.0) * scale_f;
                    let x2 = (right_c as f32 * 8.0 + 4.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][left_c]=true;
                    used[r][right_c]=true;
                    c = right_c+1;
                    continue;
                }

                // Single marker cases
                if let Some(lm) = left_marker {
                    let left_c = start-1;
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
                    if lm == '+' || lm == 'X' {
                        let x1 = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        if has_right_arrow {
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                            used[r][end+1]=true;
                            c = end+2;
                        } else {
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                            c = end+1;
                        }
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        continue;
                    }
                    if lm == '#' {
                        let x_left = (left_c as f32 * 8.0) * scale_f;
                        let y_rect = (r as f32 * 16.0 + 4.0) * scale_f;
                        elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_left), format_f32(y_rect), format_f32(8.0*scale_f), format_f32(8.0*scale_f)));
                        let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        c = end+1;
                        continue;
                    }
                    if lm == 'o' || lm == 'O' {
                        let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let left_class = match lm {
                            'o' => "solid end_marked_open_circle",
                            'O' => "solid end_marked_big_open_circle",
                            _ => "solid",
                        };
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        if has_right_arrow {
                            elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(mid_x), format_f32(y), format_f32(x2), format_f32(y)));
                            elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                            used[r][end+1]=true;
                            c = end+2;
                        } else {
