                if hl.start == c && !used[r][c] { found_h = Some(hl.clone()); break; }
            }
            if let Some(hl) = found_h {
                let start = hl.start;
                let end = hl.end;
                let ch_type = hl.ch_type;
                let left_char = hl.left_char;
                let right_char = hl.right_char;
                let has_left_arrow = left_char == '<';
                let has_right_arrow = right_char == '>';
                let left_marker = match left_char { 'o'|'O'|'*'|'#'|'+'|'X' => Some(left_char), _ => None };
                let right_marker = match right_char { 'o'|'O'|'*'|'#'|'+'|'X' => Some(right_char), _ => None };
                let y = (r as f32 * 16.0 + 8.0) * scale_f;
                if left_marker.is_none() && right_marker.is_none() && !has_left_arrow && !has_right_arrow {
                    if ch_type == '-' {
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    } else {
                        let y_base = r as f32 * 16.0 + 8.0;
                        let y1 = (y_base - 2.0) * scale_f;
                        let y2 = (y_base + 2.0) * scale_f;
                        let x1 = (start as f32 * 8.0) * scale_f;
                        let x2 = ((end+1) as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y1), format_f32(x2), format_f32(y1)));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y2), format_f32(x2), format_f32(y2)));
                    }
                    for cc in start..=end { used[r][cc]=true; }
                    c = end+1;
                    continue;
                }
                if has_right_arrow && !has_left_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    let p1y = (r as f32 * 16.0 + 4.0) * scale_f;
                    let p2x = x2 + 8.0*scale_f;
                    let p3y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32(p1y), format_f32(p2x), format_f32(y), format_f32(x2), format_f32(p3y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][end+1]=true;
                    c = end+2;
                    continue;
                }
                if has_left_arrow && !has_right_arrow && left_marker.is_none() && right_marker.is_none() {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][start-1]=true;
                    c = end+1;
                    continue;
                }
                if has_left_arrow && has_right_arrow {
                    let x1 = (start as f32 * 8.0) * scale_f;
                    let x2 = ((end+1) as f32 * 8.0) * scale_f;
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x1), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x1 - 8.0*scale_f), format_f32(y), format_f32(x1), format_f32((r as f32*16.0+12.0)*scale_f)));
                    elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                    elements.push(format!("  <polygon points=\"{},{ } {},{ } {},{}\" class=\"filled\"></polygon>", format_f32(x2), format_f32((r as f32*16.0+4.0)*scale_f), format_f32(x2 + 8.0*scale_f), format_f32(y), format_f32(x2), format_f32((r as f32*16.0+12.0)*scale_f)));
                    for cc in start..=end { used[r][cc]=true; }
                    used[r][start-1]=true;
                    used[r][end+1]=true;
                    c = end+2;
                    continue;
                }
                // both markers etc simplified: we will handle only common cases already: for this final version we keep previous logic for o,O,* and +/X and #
                if let (Some(lm), Some(rm)) = (left_marker, right_marker) {
                    let left_c = start-1;
                    let right_c = end+1;
                    let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                    let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                    if (lm == '+' || lm == 'X') && (rm == '+' || rm == 'X') {
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(left_x_center), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }
                    if lm == '#' && rm == '#' {
                        let x_left = (left_c as f32 * 8.0) * scale_f;
                        let y_rect = (r as f32 * 16.0 + 4.0) * scale_f;
                        elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_left), format_f32(y_rect), format_f32(8.0*scale_f), format_f32(8.0*scale_f)));
                        let x_right = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>", format_f32(x_right), format_f32(y_rect), format_f32(8.0*scale_f), format_f32(8.0*scale_f)));
                        let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                        let x2 = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }
                    // o/O
                    if (lm == 'o' || lm == 'O') && (rm == 'o' || rm == 'O') {
                        let mid_x = (start as f32 * 8.0 + 8.0) * scale_f;
                        let (left_class, right_class) = match (lm, rm) {
                            ('o','o') => ("solid end_marked_open_circle", "solid end_marked_open_circle"),
                            ('O','O') => ("solid end_marked_big_open_circle", "solid end_marked_big_open_circle"),
                            ('o','O') => ("solid end_marked_open_circle", "solid end_marked_big_open_circle"),
                            ('O','o') => ("solid end_marked_big_open_circle", "solid end_marked_open_circle"),
                            _ => ("solid", "solid"),
                        };
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(left_x_center), format_f32(y), left_class));
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>", format_f32(mid_x), format_f32(y), format_f32(right_x_center), format_f32(y), right_class));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }
                    // * *
                    if lm == '*' && rm == '*' {
                        let left_x_center = (left_c as f32 * 8.0 + 4.0) * scale_f;
                        let right_x_center = (right_c as f32 * 8.0 + 4.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(left_x_center), format_f32(y), format_f32(left_x_center), format_f32(y)));
                        let x1 = (left_c as f32 * 8.0 + 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", format_f32(x1), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        let x1_extra = (right_c as f32 * 8.0) * scale_f;
                        elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1_extra), format_f32(y), format_f32(right_x_center), format_f32(y)));
                        for cc in start..=end { used[r][cc]=true; }
                        used[r][left_c]=true;
                        used[r][right_c]=true;
                        c = right_c+1;
                        continue;
                    }
                }
                // single left/right markers etc. For brevity we fallback to simple line and mark
                let x1 = (start as f32 * 8.0) * scale_f;
                let x2 = ((end+1) as f32 * 8.0) * scale_f;
                elements.push(format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", format_f32(x1), format_f32(y), format_f32(x2), format_f32(y)));
                for cc in start..=end { used[r][cc]=true; }
                if left_marker.is_some() { used[r][start-1]=true; }
                if right_marker.is_some() { used[r][end+1]=true; }
                if has_left_arrow { used[r][start-1]=true; }
                if has_right_arrow { used[r][end+1]=true; }
                c = end+1;
                if right_marker.is_some() || has_right_arrow { c = end+2; }
            } else if grid[r][c] != ' ' && !used[r][c] {
                let ch = grid[r][c];
                if ch == '+' || ch == '|' {
                    let esc = escape_text(&ch.to_string());
                    let x = (c as f32 * 8.0 + 2.0) * scale_f;
                    let y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                    used[r][c]=true;
                    c+=1;
                    continue;
                }
                let start = c;
                while c < cols && !used[r][c] && grid[r][c] != ' ' {
                    let ch2 = grid[r][c];
                    if ch2 == '-' || ch2 == '=' || ch2 == '|' || ch2 == '+' { break; }
                    if ch2 == '<' || ch2 == '>' { break; }
                    c+=1;
                }
                let end = c;
                if start < end {
                    let mut word = String::new();
                    for cc in start..end { word.push(grid[r][cc]); }
                    let esc = escape_text(&word);
                    let x = (start as f32 * 8.0 + 2.0) * scale_f;
                    let y = (r as f32 * 16.0 + 12.0) * scale_f;
                    elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                    for cc in start..end { used[r][cc]=true; }
                }
                if c < cols && !used[r][c] && grid[r][c] != ' ' {
                    let ch2 = grid[r][c];
                    if ch2 == '<' || ch2 == '>' {
                        let esc = escape_text(&ch2.to_string());
                        let x = (c as f32 * 8.0 + 2.0) * scale_f;
                        let y = (r as f32 * 16.0 + 12.0) * scale_f;
                        elements.push(format!("  <text x=\"{}\" y=\"{}\" >{}</text>", format_f32(x), format_f32(y), esc));
                        used[r][c]=true;
                        c+=1;
                    }
                }
            } else { c+=1; }
        }
    }
    for el in elements { svg.push_str(&el); svg.push_str("\n"); }
    svg.push_str("</svg>\n");
    svg
}
