# Now need to patch single left marker for +/X/# as well
# Find left single block
pattern_left = r"                if let Some\(lm\) = left_marker \{\n                    let mid_x = .*?c = end\+1;\n                    continue;\n                \}"

new_left = """                if let Some(lm) = left_marker {
                    let left_c = start-1;
