pattern_right = r"                if let Some\(rm\) = right_marker \{\n                    let x1 = .*?c = end\+2;\n                    continue;\n                \}"

new_right = """                if let Some(rm) = right_marker {
                    let y = (r as f32 * 16.0 + 8.0) * scale_f;
